#pragma once
#include <cstdint>
namespace ks{class SerialSetupTask final{public:enum class Kind{Configure,Start};enum class Stage{Disable,WriteDisable,Mode,WriteMode,Baud,WriteBaud,Hold,SetDelay,Tick,AdmitDelay,Restore,Finish,Enable,WriteEnable,DispatchRx,AwaitRx,DispatchTx,AwaitTx,Complete};enum class Port{Control,Mode,Baud};explicit SerialSetupTask(Kind k):kind_(k),stage_(k==Kind::Configure?Stage::Disable:Stage::Enable){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}uint16_t remaining()const{return remaining_;}bool awaiting()const{return stage_==Stage::AwaitRx||stage_==Stage::AwaitTx;}bool resumeChild(){if(!awaiting())return false;stage_=stage_==Stage::AwaitRx?Stage::DispatchTx:Stage::Finish;return true;}
template<class Clock>unsigned nextClocks(Clock&&clock)const{switch(stage_){case Stage::WriteDisable:case Stage::WriteEnable:return 3+clock(Port::Control);case Stage::WriteMode:return 3+clock(Port::Mode);case Stage::WriteBaud:return 3+clock(Port::Baud);case Stage::Hold:case Stage::Restore:return 11;case Stage::SetDelay:return 6;case Stage::DispatchRx:case Stage::DispatchTx:return 20;case Stage::Finish:return 17;case Stage::AwaitRx:case Stage::AwaitTx:case Stage::Complete:return 0;default:return 3;}}
template<class Writer,class Clock>unsigned advanceBefore(unsigned available,Writer&&write,Clock&&clock){unsigned used=0;while(auto cost=nextClocks(clock)){if(cost>available-used)break;switch(stage_){case Stage::Disable:stage_=Stage::WriteDisable;break;case Stage::WriteDisable:write(Port::Control,0);stage_=Stage::Mode;break;case Stage::Mode:stage_=Stage::WriteMode;break;case Stage::WriteMode:write(Port::Mode,0);stage_=Stage::Baud;break;case Stage::Baud:stage_=Stage::WriteBaud;break;case Stage::WriteBaud:write(Port::Baud,0x18);stage_=Stage::Hold;break;case Stage::Hold:stage_=Stage::SetDelay;break;case Stage::SetDelay:remaining_=100;stage_=Stage::Tick;break;case Stage::Tick:--remaining_;stage_=Stage::AdmitDelay;break;case Stage::AdmitDelay:stage_=remaining_?Stage::Tick:Stage::Restore;break;case Stage::Restore:stage_=Stage::Finish;break;case Stage::Enable:stage_=Stage::WriteEnable;break;case Stage::WriteEnable:write(Port::Control,0x70);stage_=Stage::DispatchRx;break;case Stage::DispatchRx:stage_=Stage::AwaitRx;break;case Stage::DispatchTx:stage_=Stage::AwaitTx;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Kind kind_;Stage stage_;uint16_t remaining_=0;};}
